#!/usr/bin/env node
// Renders the survivor ledger summary (MUT-03, D-18) from ledger.json.
// Usage: ledger-summary.mjs <out.md>. Node builtins plus relative imports.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const DISPOSITIONS = ["pending", "gap", "equivalent", "dead"];
const compare = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

export function renderLedger(ledger) {
  const out = [
    "# Phase 67 survivor ledger",
    "",
    "Generated by tools/mutation/ledger-summary.mjs from tools/mutation/ledger.json. Do not edit by hand.",
    "",
    `Pre-triage run: ${ledger.preTriage?.runId ?? "none"}`,
    `Pre-triage SHA: ${ledger.preTriage?.sha ?? "none"}`,
    `Pre-triage trust survivors: ${ledger.preTriage?.survivorCount ?? 0}`,
    "",
  ];
  const groups = [...new Set(ledger.clusters.map((c) => c.group))].sort(
    compare,
  );
  for (const group of groups) {
    const mine = ledger.clusters.filter((c) => c.group === group);
    out.push(`## ${group}`, "");
    out.push(
      `| disposition | clusters | mutants |`,
      "|---|---|---|",
      ...DISPOSITIONS.map((d) => {
        const rows = mine.filter((c) => c.disposition === d);
        return `| ${d} | ${rows.length} | ${rows.reduce((n, c) => n + c.count, 0)} |`;
      }),
      "",
      "Top clusters by mutant count:",
      "",
    );
    const top = [...mine]
      .sort((a, b) => b.count - a.count || compare(a.id, b.id))
      .slice(0, 10);
    for (const c of top) {
      const detail =
        c.disposition === "gap"
          ? ` — test ${c.test?.file}: ${c.test?.name}`
          : c.disposition === "dead"
            ? ` — symbol ${c.symbol}`
            : c.disposition === "equivalent"
              ? ` — class ${c.equivalenceClass}`
              : "";
      out.push(`- ${c.id}: ${c.count} (${c.disposition})${detail}`);
    }
    out.push("");
    const settled = mine.filter((c) => c.disposition !== "pending");
    if (settled.length > 0) {
      out.push("Triaged clusters:", "");
      for (const c of settled.sort((a, b) => compare(a.id, b.id)))
        out.push(`- ${c.id}: ${c.disposition}, ${c.count} mutants`);
      out.push("");
    }
  }
  return `${out.join("\n")}\n`;
}

export function main(argv) {
  try {
    const target = argv[0];
    if (!target) throw new Error("usage: ledger-summary.mjs <out.md>");
    const here = dirname(fileURLToPath(import.meta.url));
    const ledger = JSON.parse(readFileSync(join(here, "ledger.json"), "utf8"));
    writeFileSync(target, renderLedger(ledger));
    return 0;
  } catch (error) {
    process.stderr.write(`ledger-summary: ${error.message}\n`);
    return 1;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href)
  process.exitCode = main(process.argv.slice(2));
